import {countries,subjects,oecd,malaysia,value,format,signed,colour} from './data.js';
const $=id=>document.getElementById(id);
let subject='science',mode='score',region='sea',selected='MYS',map=null,markers=[];
const visible=()=>countries.filter(c=>region==='global'||c.region==='sea');
function selectCountry(code,pan=true){const c=countries.find(c=>c.code===code);if(!c)return;if(c.region==='global'&&region!=='global'){region='global';$('region').value=region;}selected=code;render();if(map&&pan)map.panTo([c.lat,c.lng]);}
function render(){
 const c=countries.find(c=>c.code===selected),n=c[subject],gap=value(c,subject,'gap'),delta=c.changes[subject],label=subjects[subject];
 $('detail').innerHTML=`<p class="eyebrow">${c.code==='MYS'?'YOUR COMPARISON ANCHOR':'SELECTED COUNTRY'}</p><h2 class="country-title">${c.name}</h2><p class="panel-sub">${label} · PISA 2025</p><div class="big-score ${n==null?'no-score':''}">${format(n)}<small>${n==null?'Not included in this dataset':'mean score points'}</small></div><p class="gap-line">${gap==null?'No comparison available':c.code==='MYS'?'Malaysia is the reference for all point gaps.':`${signed(gap)} points versus Malaysia (${malaysia[subject]})`}</p><div class="stats"><div class="stat"><span>OECD average</span><strong>${oecd[subject]}</strong></div><div class="stat"><span>Gap versus OECD</span><strong>${n==null?'—':signed(n-oecd[subject])}</strong></div><div class="stat"><span>Change since 2022</span><strong>${delta==null?'—':signed(delta)+(c.ns.includes(subject)?'†':'')}</strong></div>${subject==='science'&&c.lowScience!=null?`<div class="stat"><span>Below science baseline</span><strong>${c.code==='KHM'?'≈':''}${c.lowScience}%</strong></div>`:''}</div><p class="panel-note">${c.note}</p>${c.ns.includes(subject)?'<p class="small">† The change is not statistically significant.</p>':''}${c.source?`<a class="source-link" href="${c.source}" target="_blank" rel="noopener">Read OECD country source ↗</a>`:'<a class="source-link" href="#sources">About missing data ↗</a>'}`;
 $('table-title').textContent=`${label} ${region==='sea'?'across Southeast Asia':'with selected benchmarks'}`;
 const list=visible().slice().sort((a,b)=>(b[subject]??-Infinity)-(a[subject]??-Infinity));
 $('coverage').textContent=`${list.filter(c=>c[subject]!=null).length} of ${list.length} displayed countries have verified scores`;
 $('rows').innerHTML=list.map(c=>{const n=c[subject],d=c.changes[subject];return `<tr class="${c.code===selected?'active':''}"><td><button data-country="${c.code}" aria-pressed="${c.code===selected}">${c.name}</button>${c.code==='MYS'?'<span class="anchor-tag">ANCHOR</span>':''}</td><td>${format(n)}${n==null?'':`<span class="mini-bar" style="--width:${Math.max(5,(n-300)/4)}px" aria-hidden="true"></span>`}</td><td>${n==null?'—':signed(n-malaysia[subject])}</td><td>${n==null?'—':signed(n-oecd[subject])}</td><td>${d==null?'Not available':signed(d)+(c.ns.includes(subject)?'†':'')}</td></tr>`}).join('');
 $('legend-title').textContent=`${label} · ${mode==='gap'?'gap versus Malaysia':'score points'}`;
 const keys=mode==='gap'?[['#cf7b32','Below Malaysia'],['#315ad8','Same mean'],['#008772','Above Malaysia'],['#8b97a8','Not verified']]:[['#d9904a','<400'],['#73aab6','400–449'],['#218d9e','450–499'],['#126677','500–549'],['#17364c','550+'],['#8b97a8','Not verified']];
 $('legend').innerHTML=keys.map(([col,text])=>`<span class="key"><i class="swatch" style="background:${col}"></i>${text}</span>`).join('');
 if(map){markers.forEach(m=>m.remove());markers=[];visible().forEach(c=>{const n=value(c,subject,mode);const m=L.marker([c.lat,c.lng],{keyboard:true,title:`${c.name}: ${n==null?'not verified':mode==='gap'?signed(n):n}`,alt:c.name,zIndexOffset:c.code===selected?1000:0,icon:L.divIcon({className:'pin-wrap',iconSize:[52,34],iconAnchor:[26,17],html:`<span class="pin ${c.code===selected?'selected':''} ${n==null?'missing':''}" style="--pin:${colour(n,mode)}">${n==null?'—':mode==='gap'?signed(n):n}</span>`})}).addTo(map);m.bindTooltip(c.name,{direction:'top',offset:[0,-15]});m.on('click',()=>selectCountry(c.code,false));markers.push(m);});}
}
function resetView(){if(map){if(region==='sea')map.fitBounds([[-12,91],[26,141]],{padding:[25,25],animate:false});else map.fitBounds([[-12,20],[62,143]],{padding:[30,30],animate:false});}}
$('subject').addEventListener('change',e=>{subject=e.target.value;render()});$('measure').addEventListener('change',e=>{mode=e.target.value;render()});$('region').addEventListener('change',e=>{region=e.target.value;if(region==='sea'&&countries.find(c=>c.code===selected).region!=='sea')selected='MYS';render();resetView()});$('reset').addEventListener('click',resetView);
$('rows').addEventListener('click',e=>{const b=e.target.closest('[data-country]');if(b){selectCountry(b.dataset.country);if(innerWidth<700)$('detail').scrollIntoView({behavior:'auto',block:'start'})}});
if(window.L){map=L.map('map',{scrollWheelZoom:false,minZoom:2,maxZoom:9,worldCopyJump:true});let loaded=0,errors=0;const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);tiles.on('tileload',()=>{loaded++;$('map-status').hidden=true});tiles.on('tileerror',()=>{errors++;if(!loaded&&errors>2){$('map-status').hidden=false;$('map-status').textContent='The basemap could not load. Country markers and the comparison list still work. Check your connection or reload.'}});resetView();new ResizeObserver(()=>{map.invalidateSize()}).observe($('map'));}else{$('map-status').textContent='The map library could not load. Check your internet connection or reload. All scores and country comparisons below remain available.'}
render();
// Optional WebMCP support. It uses the same visible selection action.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_pisa_comparison',description:'Select a displayed country and subject in the PISA comparison map.',inputSchema:{type:'object',properties:{countryCode:{type:'string',enum:countries.map(c=>c.code)},subject:{type:'string',enum:Object.keys(subjects)}},required:['countryCode','subject'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!countries.some(c=>c.code===input.countryCode)||!Object.hasOwn(subjects,input.subject))throw new Error('Choose a listed country and subject.');subject=input.subject;$('subject').value=subject;selectCountry(input.countryCode);const c=countries.find(c=>c.code===selected);return {country:c.name,subject:subjects[subject],score:c[subject],malaysia:malaysia[subject],oecd:oecd[subject]}}})).catch(()=>{});}catch{}}
